(()=>{'use strict';const C=window.DEMO_CONTEXT,P=window.DEMO_PAGE,A=window.REVIEWED_V23_ASSETS;if(!C||!P||!A)return;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];let layer,record,ref,returnFocus,tip,timer;
function label(item){return ($('.kodo-new-form-item-default-label',item)||$('label',item))?.textContent.trim().replace(/[:：*]/g,'');}
function close(){layer?.remove();layer=null;returnFocus?.focus();}
function open(link){const id=link.closest('[data-demo-record]').dataset.demoRecord;record=C.getLocalRecord(id);if(record?.id!==id)return;ref=link.dataset.v23Reference||link.textContent.trim();returnFocus=link;layer=document.createElement('div');layer.dataset.reviewedV23Ui='';layer.dataset.v23EditLayer='';layer.innerHTML='<div class="kodo-new-drawer kodo-new-drawer-right kodo-new-drawer-open"><div class="kodo-new-drawer-mask"></div><div class="kodo-new-drawer-content-wrapper">'+A.editHTML+'</div></div>';document.body.append(layer);const content=$('.kodo-new-drawer-content',layer);content.setAttribute('role','dialog');content.setAttribute('aria-label',(P.id==='BL-02-01'?'编辑销售订单 ':'编辑关联销售订单 ')+ref);content.setAttribute('aria-modal','true');let values={};try{values=JSON.parse(localStorage.getItem('blacklake-v23-associated-order-'+ref))||{};}catch{}$$('.kodo-new-form-item',layer).forEach(item=>{const key=label(item),input=$('input,textarea',item);if(!key||!input)return;const value=values[key]??(key==='订单编号'?ref:record.fields[key]);if(value!==undefined){input.value=String(value);const display=$('.kodo-new-select-selection-item',item);if(display)display.textContent=String(value);}});$$('.kodo-new-form-item',layer).filter(item=>label(item)==='客户').forEach(item=>{$$('span',item).filter(e=>e.textContent.trim()==='创建').forEach(e=>{e.dataset.v26CreateCustomer='';e.setAttribute('role','button');e.setAttribute('tabindex','0');});});$('[data-v23-edit-cancel]',layer)?.focus();}
if(P.id==='BL-02-01')window.REVIEWED_V25_OPEN_ORDER=open;
function wire(){if(P.id!=='BL-02-04')return;$$('[data-demo-record] [data-demo-column="来源单据"]').forEach(cell=>{if($('[data-v23-reference]',cell))return;const row=cell.closest('[data-demo-record]'),r=C.getLocalRecord(row.dataset.demoRecord);const value=String(r?.fields['来源单据']||'');if(!/^DEMO(?:-SO)?-\d+$/.test(value))return;const box=$('.editable-cell-content',cell)||cell;box.replaceChildren();const button=document.createElement('button');button.type='button';button.className='demo-observed-link';button.dataset.v23Reference=value;button.textContent=value;button.setAttribute('aria-label','编辑来源订单 '+value);button.setAttribute('aria-haspopup','dialog');box.append(button);});}
if(P.id==='BL-02-04'){const samples=C.getFilteredRecords?.().slice(0,2)||[];samples.forEach((r,i)=>{if(!/^DEMO(?:-SO)?-\d+$/.test(String(r.fields['来源单据']||'')))C.commitLocalRecord({'来源单据':'DEMO-SO-'+String(i+1).padStart(4,'0'),'来源单据类型':'销售订单'},r.id);});const prior=C.afterListRender;C.afterListRender=function(...args){prior?.apply(this,args);wire();};wire();const body=$('.kodo-art-table-tbody');if(body)new MutationObserver(wire).observe(body,{childList:true,subtree:true});}
function hideTip(){clearTimeout(timer);tip?.remove();tip=null;}
window.addEventListener('pointerover',e=>{const link=e.target.closest?.('[data-v23-reference]');if(!link)return;e.stopImmediatePropagation();hideTip();timer=setTimeout(()=>{tip=document.createElement('div');tip.dataset.v23Tooltip='';tip.setAttribute('role','tooltip');tip.textContent=link.dataset.v23Reference;document.body.append(tip);const b=link.getBoundingClientRect();Object.assign(tip.style,{left:Math.max(4,b.left+b.width/2-tip.offsetWidth/2)+'px',top:Math.max(4,b.top-tip.offsetHeight-8)+'px'});},100);},true);
window.addEventListener('pointerout',e=>{if(e.target.closest?.('[data-v23-reference]'))hideTip();},true);window.addEventListener('scroll',hideTip,true);window.addEventListener('pointerdown',hideTip,true);
window.addEventListener('click',e=>{const link=e.target.closest?.('[data-v23-reference]');if(link){e.preventDefault();e.stopImmediatePropagation();hideTip();open(link);return;}if(!e.target.closest?.('[data-v23-edit-layer]'))return;e.stopImmediatePropagation();const t=e.target;if(t.closest('[data-v26-create-customer]')){e.preventDefault();window.REVIEWED_V26_CUSTOMER_OPEN?.(layer);return;}if(t.closest('[data-v23-edit-cancel],.kodo-new-drawer-mask')){e.preventDefault();close();return;}if(t.closest('[data-v23-edit-save]')){e.preventDefault();const values={};$$('.kodo-new-form-item',layer).forEach(item=>{const key=label(item),input=$('input,textarea',item);if(key&&input)values[key]=input.value;});const customer=$('input[data-v26-customer-id]',layer);if(customer){values['客户本地ID']=customer.dataset.v26CustomerId;values['客户编号']=customer.dataset.v26CustomerCode;}if(P.id==='BL-02-01')C.commitLocalRecord(values,record.id);else localStorage.setItem('blacklake-v23-associated-order-'+ref,JSON.stringify(values));close();C.toast('已保存本地演示订单；未提交黑湖');return;}const tab=t.closest('[data-v23-edit-tab]');if(tab){const index=Number(tab.dataset.v23EditTab);$$('[role=tab]',layer).forEach((node,i)=>node.setAttribute('aria-selected',String(i===index)));const section=$$('.form-block-title__TUKCg',layer)[index];section?.scrollIntoView({block:'start'});return;}if(t.closest('button')){e.preventDefault();C.toast('该关联订单的深层操作尚未核实');}},true);
window.addEventListener('input',e=>{if(e.target.closest?.('[data-v23-edit-layer]'))e.stopImmediatePropagation();},true);
window.addEventListener('keydown',e=>{if(!layer)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return;}if(e.target.closest?.('[data-v23-edit-layer]')){e.stopImmediatePropagation();if(e.key==='Enter')e.preventDefault();}},true);
})();
